/* MUTANT: one refusal broken on purpose. The gate MUST go red against this
 * file. Generated by mut/make.py; never edited by hand.
 */
/* <ov-clearance> - a clearance is only as good as the survey under it.
 *
 * For aegis, industrial, antiseptic and holo. The
 * distance from own ship, or from a planned track, to a charted danger - drawn
 * as a BAND from the worst case the survey allows to the charted figure, with
 * the zone of confidence it came from and that zone's stated accuracy.
 *
 *   <ov-clearance label="BANTA ISLAND" unit="nm" margin="0.5"></ov-clearance>
 *   c.pick = {
 *     charted: 0.80, zoc: 'C', surveyed: '1994-03',
 *     danger: 'isolated danger',
 *   };
 *
 * ── THE REFUSAL ───────────────────────────────────────────────────────────
 *
 * 🔴 NO SINGLE CLEARANCE FIGURE FROM A CHART WHOSE CONFIDENCE IT DOES NOT
 * KNOW. With no zone of confidence the element does not fall back to the
 * charted distance, because the charted distance IS the thing in question: it
 * reads NOT QUALIFIED and says what is missing.
 *
 * The BSU's report on the PAZIFIK is the whole argument. "The CATZOC (category
 * zone of confidence) for this area is assigned a 'C', indicating a positional
 * inaccuracy of +/- 500 m or 0.27 nm. This means that a safe CPA (closest
 * point of approach) to the island of Banta and to the plotted isolated danger
 * is reduced to 0.53 nm and to 0.43 nm, respectively, in the worst case." And
 * the finding: "the ECDIS's biggest shortcoming is that the CATZOC attribute
 * is not included in the route planning. At a horizontal accuracy of +/- 500
 * m, this attribute should have been included in the alarms."
 *
 * ⚠️ AND THE OVERLAY IS NOT A SUBSTITUTE FOR THE NUMBER. S-67 §5 on the star
 * symbols: "This kind of symbology tends to clutter the screen, therefore
 * during execution of a voyage mariners will most likely de-activate this
 * setting." The BSU says the same, that the stars "are difficult for the
 * officer on watch to understand, have no effect on the automated system and
 * it is left to the user to interpret them." So the qualification has to live
 * in the figure the officer keeps on screen, not in a layer they can switch
 * off. That is why this is an element and not a chart symbol.
 *
 * And four that follow from it:
 *
 * 1. UNASSESSED IS NOT SURVEYED. Zone U is treated exactly as D. S-67 §5:
 *    "it is good practice to treat ZOC U areas with the same degree of caution
 *    as ZOC D areas." It is never drawn as though somebody had looked.
 * 2. WHERE TWO ZONES MEET, THE LESSER APPLIES. S-67 §5.2: "At that point only
 *    the lesser value of the two CATZOCs will be available for safety
 *    reasons." A clearance spanning a boundary takes the worse zone, and says
 *    which zones it spanned.
 * 3. A WORST CASE INSIDE THE MARGIN IS FLAGGED, EVEN WHERE THE CHARTED FIGURE
 *    CLEARS IT. This is the case that kills: at Banta the charted CPA was
 *    comfortable and the survey-adjusted one was not. An alarm that fires on
 *    the charted number alone is an alarm that fires too late.
 * 4. A ZONE'S ACCURACY IS QUOTED, NEVER GUESSED. The built-in table carries
 *    only the figures this kit has actually read in a source: A1 ±5 m, A2 ±20
 *    m and C ±500 m. For B and D it has no verified figure, so it REFUSES to
 *    supply one and asks the caller for the pick report's own accuracy.
 *    Inventing ±50 m for B from memory would be the same act this element
 *    exists to refuse, committed by the element itself.
 *
 * ⚠️ CATZOC's OWN GAP, which the standard states and the element repeats: "A
 * limitation of the CATZOC system is the lack of information about when a
 * survey was conducted, or whether the seabed is stable" (S-67). So the survey
 * date is printed when the pick report carries one and reads SURVEY DATE NOT
 * GIVEN when it does not. That the date belongs on the readout is INFERRED;
 * the gap it answers is stated.
 *
 * No `role="img"` on the host: its children would become presentational and
 * the zone row and the survey row would never be read.
 * The band is the only aria-hidden part, and every edge it draws is text.
 *
 * Drawn on each update. Nothing is timed and nothing runs every frame: a
 * clearance changes when the pick changes, not with the clock.
 */

import { define } from '../../../src/ov-core.js';
import '../../../src/ov-source.js';
import '../../../src/ov-refusal.js';

const M_PER_NM = 1852;

/* 🔴 ONLY WHAT HAS BEEN READ IN A SOURCE. `m` is the zone's stated horizontal
 * accuracy in metres; null means this kit has no verified figure and will not
 * invent one. A1, A2 and C are the three the BSU's reproduction of the S-57
 * table gives directly. B and D come from S-67 Annex A, which the research for
 * this element did not read, so they are null here rather than remembered. */
const ZOC = {
  A1: { m: 5, word: 'A1' },
  A2: { m: 20, word: 'A2' },
  B: { m: null, word: 'B' },
  C: { m: 500, word: 'C' },
  D: { m: null, word: 'D' },
  // Unassessed. Not a zone of its own for safety: it is D, and says so.
  U: { m: null, word: 'U', asD: true },
};
/* Worst first, so "the lesser of two zones" is a comparison this table can
 * answer without arithmetic on letters. U sits with D deliberately. */
const ORDER = ['A1', 'A2', 'B', 'C', 'D', 'U'];

const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const setText = (el, t) => { if (el && el.textContent !== t) el.textContent = t; };
const setAttr = (el, k, v) => {
  if (!el) return;
  if (v === null) { if (el.hasAttribute(k)) el.removeAttribute(k); } else if (el.getAttribute(k) !== v) el.setAttribute(k, v);
};
const num = (raw) => (raw === null || raw.trim() === '' ? null : Number(raw));
const finite = (v) => v !== null && Number.isFinite(v);
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

let serial = 0;

export class OvClearance extends HTMLElement {
  static observedAttributes = ['src', 'label', 'unit', 'margin', 'places', 'source'];

  constructor() {
    super();
    this._pick = null;
    this._malformed = 0;
    this._uid = `ov-clearance-${++serial}`;
  }

  connectedCallback() {
    if (!this._built) this.build();
    this.fetchSrc();
    this.bindSource();
    this.evaluate();
  }

  disconnectedCallback() {
    if (this.unsub) this.unsub();
    this.unsub = null;
  }

  attributeChangedCallback(name) {
    if (!this._built) return;
    if (name === 'src') { this.fetchSrc(); return; }
    if (name === 'source') this.bindSource();
    this.evaluate();
  }

  /* A scene from a file, so the element renders as plain markup on a page that
   * carries no script - the route ov-consistency and ov-coverage take. */
  async fetchSrc() {
    const src = this.getAttribute('src');
    if (!src) return;
    let data = null;
    try {
      const r = await fetch(src);
      if (!r.ok) throw new Error(String(r.status));
      data = await r.json();
    } catch { data = null; }
    if (this.getAttribute('src') !== src) return;
    this.pick = data;
  }

  bindSource() {
    if (this.unsub) this.unsub();
    this.unsub = null;
    const name = this.getAttribute('source');
    if (!name || !window.Overscan?.subscribe) return;
    this.unsub = window.Overscan.subscribe(name, (x) => { this.pick = x; });
  }

  /* ---- taking a pick report in ------------------------------------------ */

  set pick(p) {
    this._malformed = 0;
    if (!p || typeof p !== 'object') { this._pick = null; this.evaluate(); return; }
    const n = (v) => (v === null || v === undefined || !Number.isFinite(Number(v)) ? null : Number(v));
    // A pick may name one zone or the two it straddles.
    const zones = (Array.isArray(p.zoc) ? p.zoc : [p.zoc])
      .map((z) => (z === null || z === undefined ? null : String(z).toUpperCase()))
      .filter((z) => z !== null);
    for (const z of zones) if (!Object.hasOwn(ZOC, z)) this._malformed++;
    this._pick = {
      charted: n(p.charted),
      zones: zones.filter((z) => Object.hasOwn(ZOC, z)),
      // The pick report's own accuracy, in metres, which beats any table.
      accuracy: n(p.accuracy),
      surveyed: p.surveyed ? String(p.surveyed) : null,
      danger: p.danger ? String(p.danger) : null,
    };
    this.evaluate();
  }

  get pick() { return this._pick; }

  unit() { return this.getAttribute('unit') || 'nm'; }
  perUnit() { return this.unit() === 'nm' ? M_PER_NM : this.unit() === 'km' ? 1000 : 1; }
  places() {
    const p = num(this.getAttribute('places'));
    if (finite(p) && p >= 0 && p <= 4) return Math.floor(p);
    return this.unit() === 'nm' ? 2 : 0;
  }
  fmt(v) { return v === null || !Number.isFinite(v) ? '—' : v.toFixed(this.places()); }
  label() { return this.getAttribute('label') || 'CLEARANCE'; }

  /* ---- what the clearance is worth --------------------------------------- */

  evaluate() {
    if (!this._built) return this._report;
    const margin = num(this.getAttribute('margin'));
    const p = this._pick;
    const r = {
      state: 'empty', charted: null, worst: null, accuracy: null, zone: null,
      zones: [], lessened: false, asD: false, why: '', breaches: false,
      chartedClears: null, surveyed: null,
    };
    const done = () => { this._report = r; this.paint(r, margin); return r; };

    if (!p || !finite(p.charted)) { r.why = 'NO PICK REPORT'; return done(); }
    r.charted = p.charted;
    r.surveyed = p.surveyed;
    r.zones = p.zones;

    if (!p.zones.length) {
      // 🔴 The headline. No zone, no clearance: the charted figure is exactly
      // the number whose trustworthiness is unknown, so it is not the answer.
      r.state = 'unqualified';
      r.why = 'NOT QUALIFIED · the chart does not say how good the survey is';
      return done();
    }

    // Refusal 2: the lesser of the zones a clearance spans.
    const worstZone = p.zones.slice().sort((a, b) => ORDER.indexOf(b) - ORDER.indexOf(a))[0];
    r.lessened = p.zones.length > 1;
    r.zone = worstZone;
    // Refusal 1: U is D, and says so rather than quietly becoming it.
    r.asD = !!ZOC[worstZone].asD;

    // Refusal 4: the pick report's figure first, then only a table value this
    // kit can actually vouch for.
    r.accuracy = p.accuracy !== null ? p.accuracy : ZOC[worstZone].m;
    if (r.accuracy === null) {
      r.state = 'nofigure';
      r.why = `ZONE ${ZOC[worstZone].word}${r.asD ? ' (TREATED AS D)' : ''}`
        + ' · NO ACCURACY FOR THIS ZONE IN THE KIT, AND NONE IN THE PICK REPORT';
      return done();
    }

    const widen = r.accuracy / this.perUnit();
    r.worst = r.charted - widen;
    r.state = 'qualified';
    if (finite(margin)) {
      r.chartedClears = r.charted >= margin;
      r.breaches = r.charted < margin;  // MUTANT: alarm on the chart, not the truth
    }
    r.why = `ZONE ${ZOC[worstZone].word}${r.asD ? ', UNASSESSED AND TREATED AS D' : ''}`
      + ` · ±${Math.round(r.accuracy)} m`
      + (r.lessened ? ` · LESSER OF ${p.zones.join(' AND ')}` : '')
      + (p.accuracy !== null ? ' · FROM THE PICK REPORT' : '');
    return done();
  }

  get report() { return this._report; }

  /* ---- drawing ---------------------------------------------------------- */

  build() {
    this._built = true;
    this.innerHTML = `
      <div class="ov-state ov-state--edge ov-clearance__out">
        <span class="ov-aside ov-clearance__label"></span>
        <span class="ov-clearance__value"></span><span class="ov-clearance__unit"></span>
        <span class="ov-aside ov-clearance__tag"></span>
        <span class="ov-aside ov-clearance__why"></span>
      </div>
      <div class="ov-clearance__plot" aria-hidden="true">
        <div class="ov-clearance__axis"></div>
        <div class="ov-clearance__band"></div>
        <div class="ov-clearance__mark ov-clearance__mark--charted"><b></b></div>
        <div class="ov-clearance__mark ov-clearance__mark--worst"><b></b></div>
        <div class="ov-clearance__mark ov-clearance__mark--margin"><b></b></div>
      </div>
      <dl class="ov-clearance__facts">
        <div><dt>CHARTED</dt><dd class="ov-clearance__charted"></dd></div>
        <div><dt>WORST CASE</dt><dd class="ov-clearance__worst"></dd></div>
        <div><dt>SURVEY</dt><dd class="ov-clearance__survey"></dd></div>
      </dl>
      <div class="ov-clearance__breach"></div>
      <div class="ov-aside ov-clearance__rulebox"></div>
      <div class="ov-clearance__foot"></div>`;
    this.setAttribute('role', 'group');
  }

  paint(r, margin) {
    const q = (s) => this.querySelector(s);
    const u = this.unit();
    setText(q('.ov-clearance__label'), this.label());
    setText(q('.ov-clearance__rulebox'),
      finite(margin) ? `MARGIN ${this.fmt(margin)} ${u}` : 'NO MARGIN');

    setAttr(this, 'data-ov-state', r.state);
    setAttr(q('.ov-clearance__out'), 'data-ov-tone',
      r.state !== 'qualified' ? 'bad' : r.breaches ? 'bad' : 'ok');
    const shown = r.state === 'qualified';
    // A clearance the chart cannot qualify is a REFUSAL: the number exists and
    // is not an answer to the question asked.
    setAttr(this, 'data-ov-refusal', shown ? null
      : r.state === 'unqualified' || r.state === 'nofigure' ? 'unqualified' : 'unknown');
    setAttr(this, 'data-ov-qualified', shown && r.accuracy ? 'overscale' : null);
    setAttr(this, 'data-ov-breach', r.breaches ? '' : null);

    setText(q('.ov-clearance__value'), shown ? this.fmt(r.worst) : 'NOT QUALIFIED');
    setText(q('.ov-clearance__unit'), shown ? u : '');
    setText(q('.ov-clearance__tag'), shown
      ? `WORST CASE · CHARTED ${this.fmt(r.charted)} ${u} LESS THE SURVEY'S ±${Math.round(r.accuracy)} m` : '');
    setText(q('.ov-clearance__why'), r.why);

    setText(q('.ov-clearance__charted'), r.charted === null ? '—' : `${this.fmt(r.charted)} ${u}`);
    setText(q('.ov-clearance__worst'), shown ? `${this.fmt(r.worst)} ${u}` : 'NOT QUALIFIED');
    // CATZOC states its own gap, so the element repeats it rather than letting
    // a zone letter imply a recent survey.
    setText(q('.ov-clearance__survey'), r.surveyed ? `SURVEYED ${r.surveyed}` : 'SURVEY DATE NOT GIVEN');
    setAttr(q('.ov-clearance__survey'), 'data-ov-missing', r.surveyed ? null : '');

    /* Refusal 3, and the reason the element exists: the charted figure can
     * clear the margin while the honest one does not. */
    const breach = r.breaches
      ? `WORST CASE ${this.fmt(r.worst)} ${u} IS INSIDE THE ${this.fmt(margin)} ${u} MARGIN`
        + (r.chartedClears ? ` — THE CHARTED ${this.fmt(r.charted)} ${u} CLEARS IT` : '')
      : '';
    setText(q('.ov-clearance__breach'), breach);

    this.setAttribute('aria-label', shown
      ? `${this.label()}: worst case ${this.fmt(r.worst)} ${u}, charted ${this.fmt(r.charted)} ${u}, ${r.why.toLowerCase()}`
        + (breach ? `. ${breach.toLowerCase()}` : '')
      : `${this.label()}: not qualified. ${r.why.toLowerCase()}`);

    this.paintBand(r, margin);
    setText(q('.ov-clearance__foot'), this._malformed
      ? `${this._malformed} zone${this._malformed > 1 ? 's' : ''} this element does not know, ignored` : '');
  }

  /* The band runs from the worst case the survey allows to the charted figure.
   * Its WIDTH is the doubt, and that is the thing a single number hides. */
  paintBand(r, margin) {
    const q = (s) => this.querySelector(s);
    const plot = q('.ov-clearance__plot');
    const show = r.state === 'qualified';
    plot.hidden = !show;
    if (!show) return;

    const top = Math.max(r.charted, finite(margin) ? margin : 0) * 1.15 || 1;
    const at = (v) => `${clamp((v / top) * 100, 0, 100)}%`;
    q('.ov-clearance__band').style.cssText =
      `left:${at(Math.max(0, r.worst))};right:${100 - clamp((r.charted / top) * 100, 0, 100)}%`;

    /* 🔴 THE THREE MARKS COLLIDE EXACTLY WHEN THEY MATTER MOST. The case this
     * element exists for is a worst case that has fallen close to the margin,
     * and two labels at nearly the same position overprint into one unreadable
     * run: the first draft rendered "MARGIN0.5053". So they are laid out left
     * to right and anything within LANE_GAP of the mark before it is raised to
     * a second lane. Positions are untouched - only the labels move, because
     * the position is the claim. */
    const LANE_GAP = 16;                       // % of the plot, ~one label wide
    const marks = [
      ['.ov-clearance__mark--charted', r.charted, `CHARTED ${this.fmt(r.charted)}`],
      ['.ov-clearance__mark--worst', r.worst, `WORST ${this.fmt(r.worst)}`],
      ['.ov-clearance__mark--margin', finite(margin) ? margin : null, `MARGIN ${this.fmt(margin)}`],
    ];
    const live = marks
      .filter(([, v]) => finite(v))
      .map(([sel, v, text]) => ({ sel, v, text, pct: clamp((v / top) * 100, 0, 100) }))
      .sort((a, b) => a.pct - b.pct);
    let lane = 0;
    let prev = -Infinity;
    for (const m of live) {
      lane = m.pct - prev < LANE_GAP ? (lane + 1) % 2 : 0;
      m.lane = lane;
      prev = m.pct;
    }
    for (const [sel, v, text] of marks) {
      const el = q(sel);
      const on = finite(v);
      el.hidden = !on;
      if (!on) continue;
      const m = live.find((x) => x.sel === sel);
      el.style.left = `${m.pct}%`;
      setAttr(el, 'data-lane', String(m.lane));
      setText(el.querySelector('b'), text);
    }
  }
}

define('ov-clearance', OvClearance);
